(() => {
 'use strict';
 const M=AdminModel,$=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const shapes={home:'<path d="m3 10 9-7 9 7v10H3zM9 20v-7h6v7"/>',admin:'<path d="m3 8 9-5 9 5-9 5zM3 12l9 5 9-5M3 16l9 5 9-5"/>',venue:'<path d="M4 10v11h16V10M3 10l2-7h14l2 7M9 21v-7h6v7"/>',shield:'<path d="m12 3 9 4v6c0 5-9 9-9 9s-9-4-9-9V7zM7 12l3 3 7-7"/>',users:'<circle cx="9" cy="8" r="3"/><path d="M2 21v-3a7 7 0 0114 0v3M17 4a4 4 0 010 8M19 15c3 0 3 4 3 6"/>',music:'<path d="M9 18V5l11-2v13M9 8l11-2"/><circle cx="6" cy="18" r="3"/><circle cx="17" cy="16" r="3"/>',device:'<rect x="4" y="2" width="16" height="20" rx="3"/><path d="M8 6h8M10 18h4"/>',finance:'<rect x="2" y="5" width="20" height="15" rx="3"/><path d="M2 10h20M6 16h4"/>',chart:'<path d="M4 21V11M10 21V3M16 21v-9M22 21V7"/>',support:'<path d="M4 13v-2a8 8 0 0116 0v2M4 12H2v6h4v-6zm16 0h2v6h-4v-6zM18 19c0 3-4 3-6 3"/>',settings:'<path d="m10 2 4 0 1 4 4 1 3 4-3 3-1 5-4 1-3 2-3-3-5-1-1-4-2-3 3-3 1-4 4-1z"/><circle cx="12" cy="12" r="3"/>',search:'<circle cx="10" cy="10" r="7"/><path d="m15 15 6 6"/>',bell:'<path d="M5 9a7 7 0 0114 0v7l2 2H3l2-2zM9 22h6"/>',chevron:'<path d="m9 6 6 6-6 6"/>',plus:'<path d="M12 4v16M4 12h16"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l4 2"/>',warning:'<path d="m12 3 10 18H2zM12 8v6M12 17v1"/>',tag:'<path d="M3 3h9l9 9-9 9-9-9z"/><circle cx="7" cy="7" r="1"/>',send:'<path d="m2 3 20 9-20 9 4-9zm4 9h16"/>',book:'<path d="m2 8 10-5 10 5-10 5zM6 10v7c4 3 8 3 12 0v-7"/>',wave:'<path d="M3 10v4M7 7v10M11 3v18M15 6v12M19 8v8M23 10v4"/>'};
 const icon=n=>'<svg viewBox="0 0 24 24" aria-hidden="true">'+(shapes[n]||shapes.admin)+'</svg>';
 const nav=[['overview','Админка','admin'],['venues','Заведения','venue'],['moderation','Модерация','shield'],['users','Пользователи','users'],['playlists','Плейлисты','music'],['devices','Устройства','device'],['finance','Финансы','finance'],['analytics','Аналитика','chart'],['support','Поддержка','support'],['settings','Настройки','settings']];
 const labels={issues:'Проблемные',active:'Активно',pending:'На модерации',attention:'Требует внимания',offline:'Офлайн',blocked:'Заблокировано',rejected:'Отклонено',paid:'Оплачен',refunded:'Возврат',failed:'Ошибка'};
 const localKey='promo-air-admin-demo-v1';let state=M.seed();try{const s=JSON.parse(localStorage.getItem(localKey));if(M.validate(s))state=s}catch{}
 let page='overview',filters={query:'',status:'',city:'',plan:''},paymentFilter='',modalSave=null,toastTimer,lastFocus;
 const payments=[{id:'DEMO-101',venue:'Surf Coffee',date:'2026-10-15',amount:999000,status:'paid'},{id:'DEMO-102',venue:'PROMO Bar',date:'2026-10-15',amount:1499000,status:'paid'},{id:'DEMO-103',venue:'Hotel Chill',date:'2026-10-16',amount:1499000,status:'pending'},{id:'DEMO-104',venue:'Spa Mia',date:'2026-10-14',amount:999000,status:'refunded'},{id:'DEMO-105',venue:'Fit Zone',date:'2026-10-16',amount:499000,status:'failed'}];
 const money=k=>new Intl.NumberFormat('ru-RU',{style:'currency',currency:'RUB',maximumFractionDigits:0}).format(k/100);
 const art=v=>'<span class="art" aria-hidden="true" style="--pos:'+['0% 0%','50% 0%','100% 0%','0% 100%','50% 100%','100% 100%'][v.art]+'"></span>';
 const pill=s=>'<span class="pill status-'+s+'"><i class="light"></i>'+esc(labels[s]||s)+'</span>';
 const btn=(label,action,cls='',id='')=>'<button type="button" class="button '+cls+'" data-action="'+action+'"'+(id?' data-id="'+esc(id)+'"':'')+'>'+label+'</button>';
 const go=(label,target,cls='')=>'<button type="button" class="button '+cls+'" data-page="'+target+'">'+label+'</button>';
 const title=(h,p)=>'<div class="page-title"><h1>'+h+'</h1><p>'+p+'</p></div>';
 const sectionHead=(label,i,extra='')=>'<div class="section-head">'+icon(i)+'<h2>'+label+'</h2>'+extra+'</div>';
 const notice='<p class="note">Демонстрационные данные. Реальные аккаунты, устройства и платежи не подключены.</p>';
 function notify(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500)}
 function save(){try{localStorage.setItem(localKey,JSON.stringify(state));return true}catch{notify('Браузер не сохранил изменения. Они доступны только до перезагрузки.');return false}}
 function log(text){state.logs.unshift({text,at:new Date().toISOString()});state.logs=state.logs.slice(0,100);save()}
 function stats(){const vs=state.venues;return '<div class="stats">'+[['venue',vs.length,'Всего заведений',''],['chart',vs.filter(v=>v.status==='active').length,'Активные','active'],['clock',vs.filter(v=>v.status==='pending').length,'На модерации','pending'],['warning',vs.filter(v=>['attention','offline','blocked'].includes(v.status)).length,'Проблемные','issues']].map(([i,n,label,s])=>'<button class="stat" data-stat="'+s+'"><span class="stat-icon">'+icon(i)+'</span><span><strong>'+n+'</strong><small>'+label+'</small></span><span class="arrow">›</span></button>').join('')+'</div>'}
 function select(name,caption,values){return '<select class="field" data-filter="'+name+'" aria-label="'+caption+'"><option value="">'+caption+': все</option>'+values.map(v=>'<option value="'+esc(v)+'" '+(filters[name]===v?'selected':'')+'>'+esc(name==='status'?labels[v]:v)+'</option>').join('')+'</select>'}
 function filtersHtml(){return '<div class="filters"><input class="field" id="venue-search" aria-label="Поиск заведений" placeholder="Поиск по названию, городу или владельцу…" value="'+esc(filters.query)+'">'+select('status','Статус',[...M.statuses,'issues'])+select('city','Город',[...new Set(state.venues.map(v=>v.city))].sort())+select('plan','Тариф',M.plans)+btn(icon('plus')+'Добавить заведение','new','primary')+'</div>'}
 function filtered(){if(filters.status==='issues')return M.filter(state.venues,{...filters,status:''}).filter(v=>['attention','offline','blocked'].includes(v.status));return M.filter(state.venues,filters)}
 function venueRows(list){return list.map(v=>'<tr><td><div class="venue-cell">'+art(v)+'<span><strong>'+esc(v.name)+'</strong><small>'+esc(v.category)+'</small></span></div></td><td>'+esc(v.city)+'</td><td><span class="pill">'+esc(v.category)+'</span></td><td><span class="pill">'+esc(v.plan)+'</span></td><td>'+pill(v.status)+'</td><td>'+v.devices+'</td><td><span class="music-state '+(v.music==='Играет'?'':'muted')+'">'+icon('wave')+esc(v.music)+'</span></td><td><span class="pill">Демо</span></td><td><button class="row-action" data-action="detail" data-id="'+esc(v.id)+'" aria-label="Карточка '+esc(v.name)+'">···</button></td></tr>').join('')}
 function table(){const list=filtered();return '<section class="panel table-panel">'+filtersHtml()+'<div class="table-wrap" role="region" aria-label="Таблица заведений, прокручивается по горизонтали" tabindex="0"><table class="data-table"><thead><tr>'+['Заведение','Город','Категория','Тариф','Статус','Устройства','Музыка','Последняя активность','Действия'].map(t=>'<th scope="col">'+t+'</th>').join('')+'</tr></thead><tbody id="venue-rows">'+venueRows(list)+'</tbody></table><div id="venue-empty" class="empty" '+(list.length?'hidden':'')+'>Ничего не найдено. Измените фильтры.</div></div><div class="table-bottom"><span id="result-count">Найдено: '+list.length+' из '+state.venues.length+'</span><button data-action="clear-filters">Сбросить фильтры</button></div></section>'}
 function refreshRows(){const list=filtered();$('#venue-rows').innerHTML=venueRows(list);$('#venue-empty').hidden=Boolean(list.length);$('#result-count').textContent='Найдено: '+list.length+' из '+state.venues.length}
 function pendingList(){const pending=state.venues.filter(v=>v.status==='pending');return '<section class="panel">'+sectionHead('Заявки на модерацию','venue','<span class="count">'+pending.length+'</span>')+'<div class="pending-list">'+(pending.length?pending.slice(0,3).map(v=>'<article class="pending-row">'+art(v)+'<div class="pending-info"><strong>'+esc(v.name)+'</strong><small>'+esc(v.category)+' · '+esc(v.city)+'</small><small>Демо-заявка</small></div><div class="review-controls"><button data-action="approve" data-id="'+esc(v.id)+'" aria-label="Одобрить '+esc(v.name)+'">✓</button><button class="reject" data-action="reject" data-id="'+esc(v.id)+'" aria-label="Отклонить '+esc(v.name)+'">×</button></div></article>').join(''):'<p class="empty">Все заявки рассмотрены.</p>')+'</div>'+go('Все заявки на модерацию →','moderation','full-button')+'</section>'}
 function quicks(){return '<section class="panel">'+sectionHead('Быстрые действия','venue')+'<div class="quick-links">'+[['tag','Назначить тариф','pick-plan'],['venue','Открыть карточку заведения','pick-detail'],['shield','Заблокировать заведение','pick-block'],['send','Написать владельцу','pick-message']].map(([i,t,a])=>'<button class="quick-link" data-action="'+a+'">'+icon(i)+'<b>'+t+'</b><span>›</span></button>').join('')+'</div></section>'}
 function activity(){return '<section class="panel">'+sectionHead('Последние действия','admin',go('Все действия →','analytics'))+(state.logs.length?state.logs.slice(0,4).map(l=>'<div class="activity-row"><i class="light"></i><span>'+esc(l.text)+'</span><time>'+esc(new Date(l.at).toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit'}))+'</time></div>').join(''):'<div class="empty">Пока действий нет.<br>Здесь появятся изменения этого демо-сеанса.</div>')+'</section>'}
 function supportCard(){return '<section class="panel">'+sectionHead('Поддержка и подсказки','support')+'<div class="support-scene"><h3>Нужна помощь?</h3><p>Инструкции по модерации, финансам и управлению заведениями.</p>'+go('Перейти в базу знаний','support','primary')+'<span class="mia" role="img" aria-label="Мия, помощник"></span></div></section>'}
 function materials(){return '<section class="panel materials">'+sectionHead('Полезные материалы','book')+'<div class="materials-list">'+['Как проходит модерация?','Настройка устройств','Финансы и платежи'].map((t,i)=>'<button data-action="guide" data-guide="'+i+'"><span>▶</span><span>'+t+'<small>Краткая инструкция</small></span></button>').join('')+'</div><img class="admin-mascot" src="/assets/admin-dj.webp" alt="Диджей в чёрном худи, коралловых очках и чёрных наушниках"></section>'}
 function overview(){return '<div class="main-grid"><div class="main-left">'+title('Админка','Управление заведениями, модерацией и статусами сети.')+stats()+table()+'</div><aside class="right-rail" aria-label="Оперативное управление">'+pendingList()+quicks()+'</aside></div><div class="bottom-grid">'+activity()+supportCard()+materials()+'</div>'}
 function venues(){return title('Заведения','Вся сеть в одном месте. Фильтры, владельцы и карточки заведений.')+stats()+table()+notice}
 function moderation(){const list=state.venues.filter(v=>v.status==='pending');return title('Модерация','Проверяйте данные заведения и фиксируйте решение с причиной.')+'<div class="toolbar"><p>Ожидают решения: '+list.length+'</p>'+go('История решений','analytics')+'</div><div class="cards">'+(list.length?list.map(v=>'<article class="panel card">'+art(v)+'<h3>'+esc(v.name)+'</h3><p>'+esc(v.category)+' · '+esc(v.city)+'<br>Владелец: '+esc(v.owner)+'<br>Тариф: '+esc(v.plan)+'</p><div class="card-actions">'+btn('Подробнее','detail','',v.id)+btn('Одобрить','approve','primary',v.id)+btn('Отклонить','reject','danger',v.id)+'</div></article>').join(''):'<div class="panel empty">Очередь пуста. Все заявки рассмотрены.</div>')+'</div>'+notice}
 function users(){const owners=[...new Set(state.venues.map(v=>v.owner))];return title('Пользователи','Владельцы заведений и их доступ к сети.')+'<section class="panel"><div class="table-wrap"><table class="data-table"><thead><tr><th>Пользователь</th><th>Роль</th><th>Заведения</th><th>Действия</th></tr></thead><tbody>'+owners.map(o=>{const vs=state.venues.filter(v=>v.owner===o);return '<tr><td>'+esc(o)+'</td><td><span class="pill">Владелец · демо</span></td><td>'+vs.map(v=>esc(v.name)).join(', ')+'</td><td>'+btn('Карточка заведения','detail','',vs[0].id)+'</td></tr>'}).join('')+'</tbody></table></div></section><p class="note">Роли здесь доступны для просмотра. Реальное назначение прав подключается к серверной системе доступа платформы.</p>'}
 function playlists(){return title('Плейлисты','Библиотека музыкальных форматов для заведений.')+'<div class="cards">'+[['Morning Soul','Soul / Jazz','Утро'],['Sunset Lounge','Lounge / Acoustic','День'],['Night Groove','Funk / Disco','Вечер'],['Soft Motion','Ambient / Chill','Wellness']].map(([name,g,m])=>'<article class="panel card"><span class="stat-icon">'+icon('music')+'</span><h3 style="margin-top:18px">'+name+'</h3><p>'+g+' · '+m+'<br>Визуальный формат, не реальная запись каталога.</p>'+btn('О формате','format','','')+'</article>').join('')+'</div>'+notice}
 function devices(){return title('Устройства','Привязка к заведениям и состояние подключения.')+'<section class="panel"><div class="table-wrap"><table class="data-table"><thead><tr><th>Заведение</th><th>Количество</th><th>Телеметрия</th><th>Действия</th></tr></thead><tbody>'+state.venues.map(v=>'<tr><td>'+esc(v.name)+'</td><td>'+v.devices+' в макете</td><td><span class="pill">Не подключена</span></td><td>'+btn('Карточка','detail','',v.id)+'</td></tr>').join('')+'</tbody></table></div></section><p class="note">Количество устройств взято из макета. Реальный heartbeat, pairing и команды управления отсутствуют. Статус «Играет» в таблице также демонстрационный.</p>'}
 function finance(){const t=M.totals(payments),list=payments.filter(p=>!paymentFilter||p.status===paymentFilter);return title('Финансы','Платежи, счета и возвраты. Финансовый обзор администратора.')+'<p class="finance-summary">Пример операций за 14–16 октября 2026 · все суммы вымышлены · RUB</p><div class="stats money">'+[['finance',money(t.paid),'Оплачено'],['clock',money(t.pending),'Ожидает оплаты'],['finance',money(t.refunded),'Возвращено'],['warning',payments.filter(p=>p.status==='failed').length,'Ошибок оплаты']].map(([i,n,l])=>'<div class="stat"><span class="stat-icon">'+icon(i)+'</span><span><strong>'+n+'</strong><small>'+l+'</small></span></div>').join('')+'</div><div class="toolbar"><div class="status-tabs">'+[['','Все'],['paid','Оплачено'],['pending','Ожидает'],['refunded','Возвраты'],['failed','Ошибки']].map(([s,l])=>'<button data-payment="'+s+'" aria-pressed="'+(s===paymentFilter)+'">'+l+'</button>').join('')+'</div>'+btn('Выгрузить пример CSV','export')+'</div><section class="panel"><div class="table-wrap"><table class="data-table"><thead><tr><th>Счёт</th><th>Заведение</th><th>Дата</th><th>Сумма</th><th>Статус</th><th>Детали</th></tr></thead><tbody>'+list.map(p=>'<tr><td>'+p.id+'</td><td>'+p.venue+'</td><td>'+p.date+'</td><td>'+money(p.amount)+'</td><td>'+pill(p.status)+'</td><td>'+btn('Операция','payment','',p.id)+'</td></tr>').join('')+'</tbody></table></div></section><p class="note">Нет доступа к платёжному провайдеру. Возвраты, списания и изменение оплаченных сумм здесь недоступны. Сверка, бухгалтерские документы и финансовые права подключаются в рабочем проекте.</p>'}
 function analytics(){return title('Аналитика и журнал','Изменения в этом демо-сеансе и состояние макета сети.')+stats()+'<section class="panel">'+sectionHead('Журнал действий','admin')+(state.logs.length?state.logs.map(l=>'<div class="activity-row"><i class="light"></i><span>'+esc(l.text)+'</span><time>'+esc(new Date(l.at).toLocaleString('ru-RU'))+'</time></div>').join(''):'<div class="empty">Действий пока нет.</div>')+'</section><p class="note">Это локальный журнал, его можно изменить средствами браузера. В production нужен неизменяемый серверный audit log. Прослушивания, выручка и бизнес-метрики здесь не измеряются.</p>'}
 const guides=[['Как проходит модерация?','Откройте карточку, проверьте владельца и данные заведения. Одобрение активирует демо-запись. Для отклонения обязательно укажите причину. В рабочем сервисе решение проверяется и фиксируется сервером.'],['Настройка устройств','Устройства должны быть привязаны к заведению. Реальный статус определяется heartbeat, а успешное выполнение команды подтверждает устройство. В этом прототипе нет сетевых команд и реальной телеметрии.'],['Финансы и платежи','Раздел «Финансы» показывает счета, оплаты и возвраты. Тариф назначается отдельно в карточке заведения. Платёжные операции выполняются существующим billing backend, с проверкой прав и журналированием.']];
 function support(){return title('Поддержка','База знаний и черновики обращений владельцам.')+'<div class="main-grid"><section class="panel knowledge">'+guides.map(([t,p])=>'<details><summary>'+t+'</summary><p>'+p+'</p></details>').join('')+'<h2>Черновики сообщений</h2><div class="message-list">'+(state.messages.length?state.messages.map(m=>'<article><strong>'+esc(m.venue)+'</strong><p>'+esc(m.text)+'</p><p>Черновик, не отправлен.</p></article>').join(''):'<p class="empty">Сохранённых черновиков нет.</p>')+'</div></section><aside>'+materials()+'</aside></div>'}
 function settings(){return title('Настройки','Окружение, доступ и параметры интеграции.')+'<section class="panel"><dl class="details"><dt>Режим</dt><dd>Интерактивный демонстрационный прототип</dd><dt>Хранение</dt><dd>Только этот браузер</dd><dt>Права</dt><dd>Макет администратора, серверная роль не подключена</dd><dt>Биллинг</dt><dd>Операции недоступны</dd><dt>Часовые пояса</dt><dd>Подключаются из настроек заведений</dd><dt>Дизайн</dt><dd>Promo.Art</dd></dl><p class="note">Раздел не изменяет настройки реальной платформы. Сброс удаляет только локальные демо-правки этой админки, кабинет владельца не затрагивается.</p>'+btn('Сбросить демо-изменения','reset','danger')+'</section>'}
 const pages={overview,venues,moderation,users,playlists,devices,finance,analytics,support,settings};
 function closeMenu(){document.body.classList.remove('menu-open');$('#scrim').hidden=true;$('#open-menu').setAttribute('aria-expanded','false')}
 function render(next=page,keep=false){page=pages[next]?next:'overview';$('#main').innerHTML=pages[page]();document.querySelectorAll('.nav-link').forEach(b=>{if(b.dataset.page===page)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')});if(!keep){if(location.hash!=='#'+page)history.pushState(null,'','#'+page);window.scrollTo({top:0,behavior:'instant'})}closeMenu();const s=$('#venue-search');if(s)s.oninput=()=>{filters.query=s.value;refreshRows()};document.querySelectorAll('[data-filter]').forEach(s=>s.onchange=()=>{filters[s.dataset.filter]=s.value;refreshRows()})}
 function modal(title,body,submit,callback){lastFocus=document.activeElement;$('#modal-title').textContent=title;$('#modal-body').innerHTML=body+'<p class="error" id="modal-error" role="alert" hidden></p>';$('#modal-actions').innerHTML='<button type="button" class="button" data-action="close">'+(submit?'Отмена':'Закрыть')+'</button>'+(submit?'<button type="submit" class="button primary">'+submit+'</button>':'');modalSave=callback;$('#dialog').showModal()}
 const field=(label,name,value='',required=true)=>'<label>'+label+'<input class="field" name="'+name+'" value="'+esc(value)+'" maxlength="100" '+(required?'required':'')+'></label>';
 const find=id=>state.venues.find(v=>v.id===id);
 function detail(id){const v=find(id);if(!v)return;modal(v.name,'<dl class="details"><dt>Владелец</dt><dd>'+esc(v.owner)+'</dd><dt>Город</dt><dd>'+esc(v.city)+'</dd><dt>Категория</dt><dd>'+esc(v.category)+'</dd><dt>Тариф</dt><dd>'+esc(v.plan)+'</dd><dt>Статус</dt><dd>'+pill(v.status)+'</dd></dl><p>Демонстрационная карточка. Реальный аккаунт не изменяется.</p><div class="card-actions">'+btn('Изменить','edit','',id)+btn('Назначить тариф','plan','',id)+btn('Черновик сообщения','message','',id)+(v.status==='pending'?btn('Одобрить','approve','primary',id)+btn('Отклонить','reject','danger',id):v.status==='blocked'?btn('Разблокировать','restore','',id):btn('Заблокировать','block','danger',id))+'</div>')}
 function mutate(id,action){const v=find(id);if(!v)return;const labels={approve:'Одобрить заявку',reject:'Отклонить заявку',block:'Заблокировать заведение',restore:'Снять блокировку'};const reason=['block','reject'].includes(action);modal(labels[action],'<p>'+esc(v.name)+' · '+esc(v.city)+'. Изменится только демонстрационная запись.</p>'+(reason?'<label>Причина<textarea class="field" name="reason" required maxlength="500"></textarea></label>':''),'Подтвердить',d=>{const i=state.venues.findIndex(v=>v.id===id);state.venues[i]=M.transition(state.venues[i],action,String(d.get('reason')||''));log(labels[action]+': '+v.name+(reason?' · '+d.get('reason').trim():''));render(page,true);notify('Демо-статус обновлён')})}
 function edit(id){const v=find(id);modal(v?'Изменить заведение':'Добавить заведение',field('Название','name',v?.name)+field('Город','city',v?.city)+field('Владелец','owner',v?.owner)+'<label>Категория<select class="field" name="category">'+['Кофейня','Ресторан','Бар','Фитнес','Отель','СПА'].map((t,i)=>'<option value="'+i+'" '+(v?.art===i?'selected':'')+'>'+t+'</option>').join('')+'</select></label><p>Новые демо-заведения поступают на модерацию.</p>','Сохранить',d=>{const name=d.get('name').trim(),city=d.get('city').trim(),owner=d.get('owner').trim();if(!name||!city||!owner)throw Error('Заполните название, город и владельца');if(!v&&state.venues.length>=200)throw Error('Демо ограничено 200 заведениями');const art=+d.get('category'),entry={...(v||{id:'v'+Date.now(),plan:'Старт',status:'pending',devices:0,music:'Нет музыки'}),name,city,owner,art,category:['Кофейня','Ресторан','Бар','Фитнес','Отель','СПА'][art]};if(v)state.venues[state.venues.indexOf(v)]=entry;else state.venues.push(entry);log((v?'Изменено':'Добавлено')+' заведение: '+name);render(page,true);notify('Демо-запись сохранена')})}
 function plan(id){const v=find(id);if(!v)return;modal('Назначить тариф','<p>'+esc(v.name)+'. Это демонстрационное назначение, без списания и изменения подписки.</p><label>Тариф<select name="plan" class="field">'+M.plans.map(p=>'<option '+(v.plan===p?'selected':'')+'>'+p+'</option>').join('')+'</select></label>','Назначить в демо',d=>{v.plan=d.get('plan');log('Назначен демо-тариф «'+v.plan+'»: '+v.name);render(page,true)})}
 function message(id){const v=find(id);if(!v)return;modal('Написать владельцу','<p>'+esc(v.owner)+' · '+esc(v.name)+'</p><label>Текст сообщения<textarea class="field" name="text" maxlength="1000" required></textarea></label><p>Сохранится только черновик. Сообщение никому не отправляется.</p>','Сохранить черновик',d=>{const text=d.get('text').trim();if(!text)throw Error('Введите текст сообщения');if(state.messages.length>=100)throw Error('Достигнут лимит 100 демо-черновиков');state.messages.unshift({venue:v.name,text});log('Сохранён черновик владельцу: '+v.name);render(page,true);notify('Черновик сохранён, отправки нет')})}
 function pick(action){modal('Выберите заведение','<label>Заведение<select name="venue" class="field">'+state.venues.map(v=>'<option value="'+esc(v.id)+'">'+esc(v.name)+'</option>').join('')+'</select></label>','Продолжить',d=>{const id=d.get('venue');setTimeout(()=>({plan,detail,block:id=>mutate(id,'block'),message})[action](id),0)})}
 function exportCsv(){const rows=[['Счёт','Заведение','Дата','Сумма RUB','Статус'],...payments.filter(p=>!paymentFilter||p.status===paymentFilter).map(p=>[p.id,p.venue,p.date,(p.amount/100).toFixed(2),labels[p.status]])];const blob=new Blob(['\ufeff'+rows.map(r=>r.map(M.csvCell).join(';')).join('\r\n')],{type:'text/csv;charset=utf-8'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='PROMO_AIR_demo_finance.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('Выгружен CSV демонстрационных операций')}
 const actions={new:()=>edit(),detail,edit,plan,message,approve:id=>mutate(id,'approve'),reject:id=>mutate(id,'reject'),block:id=>mutate(id,'block'),restore:id=>mutate(id,'restore'),'pick-plan':()=>pick('plan'),'pick-detail':()=>pick('detail'),'pick-block':()=>pick('block'),'pick-message':()=>pick('message'),close:()=>$('#dialog').close(),'clear-filters':()=>{filters={query:'',status:'',city:'',plan:''};render(page,true)},notifications:()=>modal('Уведомления','<p>Ожидают модерации: '+state.venues.filter(v=>v.status==='pending').length+'. Это локальная очередь макета.</p>'),profile:()=>modal('Администратор · демо','<p>Серверная авторизация и права не подключены. Не используйте прототип для реальных административных операций.</p>'),format:()=>modal('Музыкальный формат','<p>Это визуальный пример. Доступность реальных треков и права каталога подключаются через существующую библиотеку платформы.</p>'),payment:id=>{const p=payments.find(p=>p.id===id);if(p)modal('Операция '+p.id,'<p>'+p.venue+' · '+money(p.amount)+' · '+labels[p.status]+'</p><p>Демонстрационный счёт, не платёжный документ. Реальные платежи и возвраты недоступны.</p>')},export:exportCsv,reset:()=>modal('Сбросить демо-изменения?','<p>Будут удалены локальные правки, журнал и черновики этой админки. Вернутся исходные демонстрационные записи. Реальный сервис и кабинет владельца не затрагиваются.</p>','Сбросить',()=>{state=M.seed();filters={query:'',status:'',city:'',plan:''};save();render('overview');notify('Демо восстановлено')})};
 $('#nav').innerHTML='<a class="nav-link" href="/cabinet/">'+icon('home')+'Главная</a>'+nav.map(([id,t,i])=>'<button class="nav-link" data-page="'+id+'">'+icon(i)+t+(id==='moderation'?'<span class="dot"></span>':'')+'</button>').join('');
 document.querySelectorAll('[data-icon]').forEach(x=>x.innerHTML=icon(x.dataset.icon));
 document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.page)render(b.dataset.page);if(b.dataset.action){if($('#dialog').open&&!['close'].includes(b.dataset.action))$('#dialog').close();actions[b.dataset.action]?.(b.dataset.id)}if(b.hasAttribute('data-stat')){filters={query:'',status:b.dataset.stat,city:'',plan:''};render('venues')}if(b.hasAttribute('data-payment')){paymentFilter=b.dataset.payment;render('finance',true)}if(b.hasAttribute('data-guide')){const g=guides[+b.dataset.guide];modal(g[0],'<p>'+g[1]+'</p>')}});
 $('#modal-form').onsubmit=e=>{e.preventDefault();try{modalSave?.(new FormData(e.target));$('#dialog').close()}catch(error){$('#modal-error').textContent=error.message;$('#modal-error').hidden=false}};$('#modal-close').onclick=()=>$('#dialog').close();$('#dialog').addEventListener('close',()=>{if(lastFocus?.isConnected)lastFocus.focus()});
 $('#global-search').onsubmit=e=>{e.preventDefault();filters={query:new FormData(e.target).get('query').trim(),status:'',city:'',plan:''};render('venues')};$('#open-menu').onclick=()=>{document.body.classList.add('menu-open');$('#scrim').hidden=false;$('#open-menu').setAttribute('aria-expanded','true');$('#close-menu').focus()};$('#close-menu').onclick=()=>{closeMenu();$('#open-menu').focus()};$('#scrim').onclick=closeMenu;
 document.addEventListener('keydown',e=>{if(e.key==='Escape')closeMenu();if(e.key==='Tab'&&document.body.classList.contains('menu-open')){const items=[...$('#sidebar').querySelectorAll('a[href],button')].filter(x=>x.getClientRects().length),first=items[0],last=items.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
 window.addEventListener('popstate',()=>render(location.hash.slice(1)||'overview'));window.addEventListener('hashchange',()=>{const next=location.hash.slice(1)||'overview';if(next!==page)render(next)});render(location.hash.slice(1)||'overview');
})();
